export default function Edition14Gallery() {
  return (
    <div className="py-12">
      <h2 className="text-3xl font-bold text-primary mb-8">Galerie de la 14ème Édition</h2>
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {Array.from({ length: 12 }).map((_, index) => (
          <div key={index} className="relative aspect-square overflow-hidden rounded-lg bg-gray-100">
            <img
              src={`/images/editions/edition14-${index + 1}.jpeg`}
              alt={`Édition 14 - Image ${index + 1}`}
              className="w-full h-full object-cover hover:scale-105 transition-transform duration-300"
              loading="lazy"
              onError={(e) => {
                // Gestion des images manquantes
                const target = e.target as HTMLImageElement;
                target.src = '/images/placeholder.jpg'; // Ajoutez une image de remplacement si nécessaire
                target.alt = 'Image non disponible';
              }}
            />
          </div>
        ))}
      </div>
    </div>
  )
}
